using System;
using System.IO;
using NUnit.Framework;
using UnityEditor;
using UnityEngine;

/// <summary>
/// Verifies that the exported independent UI PNGs reproduce the original
/// TopHUD pixels exactly, with no autogenerated ornaments or modified colors.
/// Also checks that BOTH playable mouse scenes have the splitter attached.
/// </summary>
public sealed class MouseTopHUDSeparationTests
{
    private const string Source = "Assets/Image2/HUD.3.png";
    private const string Folder = "Assets/Resources/RuruArt/UI/HUDParts/";
    private const string ComponentGuid = "8ec4302eb8a04afcb8141b64c9efec38";
    private static readonly string[] Names =
        { "HUD_IconSide", "HUD_LeftRule", "HUD_CenterRule", "HUD_RightRule" };
    private static readonly int[] Edges = { 0, 135, 560, 1200, 1672 };

    [Test]
    public void OriginalHudIsSeparatedWithoutChangingAnyPixel()
    {
        Assert.IsTrue(File.Exists(Source), "Original approved HUD is missing.");

        Texture2D original = ReadPng(Source);
        try
        {
            Assert.AreEqual(1672, original.width);
            Assert.AreEqual(941, original.height);

            Color32[] pixels = original.GetPixels32();
            const int yBottom = 941 - 168;
            const int pieceHeight = 168 - 40;

            for (int i = 0; i < Names.Length; i++)
            {
                string path = Folder + Names[i] + ".png";
                Assert.IsTrue(File.Exists(path),
                    "Missing separately generated PNG: " + path);

                Texture2D part = ReadPng(path);
                try
                {
                    int pieceWidth = Edges[i + 1] - Edges[i];
                    Assert.AreEqual(pieceWidth, part.width, path);
                    Assert.AreEqual(pieceHeight, part.height, path);

                    Sprite imported = AssetDatabase.LoadAssetAtPath<Sprite>(path);
                    Assert.IsNotNull(imported, "Not imported as Sprite: " + path);

                    Color32[] partPixels = part.GetPixels32();
                    for (int y = 0; y < pieceHeight; y++)
                    {
                        for (int x = 0; x < pieceWidth; x++)
                        {
                            Color32 expected = pixels[
                                (yBottom + y) * original.width + Edges[i] + x];
                            Color32 actual = partPixels[y * pieceWidth + x];

                            Assert.AreEqual(expected.r, actual.r,
                                path + " R @" + x + "," + y);
                            Assert.AreEqual(expected.g, actual.g,
                                path + " G @" + x + "," + y);
                            Assert.AreEqual(expected.b, actual.b,
                                path + " B @" + x + "," + y);
                            Assert.AreEqual(expected.a, actual.a,
                                path + " A @" + x + "," + y);
                        }
                    }
                }
                finally
                {
                    UnityEngine.Object.DestroyImmediate(part);
                }
            }
        }
        finally
        {
            UnityEngine.Object.DestroyImmediate(original);
        }
    }

    [TestCase("Assets/Scene/Mouse.unity")]
    [TestCase("Assets/Scene/Tutorial.unity")]
    public void SceneHasSplitHudComponentAndOriginalFallback(string scene)
    {
        Assert.IsTrue(File.Exists(scene), "Scene missing: " + scene);
        string text = File.ReadAllText(scene);

        StringAssert.Contains("guid: " + ComponentGuid, text);
        StringAssert.Contains("component: {fileID: 947025314}", text);
        StringAssert.Contains("guid: c68a6d6b5224f7942aa89d252c785bc2", text);
    }

    private static Texture2D ReadPng(string path)
    {
        Texture2D result = new Texture2D(2, 2,
            TextureFormat.RGBA32, false);
        if (!result.LoadImage(File.ReadAllBytes(path), false))
            throw new InvalidOperationException("Cannot decode " + path);
        return result;
    }
}
